__attribute__((unused)) static void
tracelib__assert(struct tracelib *s __attribute__((unused)))
{
#ifdef __cplusplus
#define _Static_assert static_assert
#endif
	_Static_assert(sizeof(s->rodata->cfg_theta) == 4, "unexpected size of 'cfg_theta'");
	_Static_assert(sizeof(s->rodata->cfg_cov_mode) == 1, "unexpected size of 'cfg_cov_mode'");
	_Static_assert(sizeof(s->rodata->cfg_hdr_len) == 4, "unexpected size of 'cfg_hdr_len'");
	_Static_assert(sizeof(s->rodata->cfg_hdr_lc) == 32, "unexpected size of 'cfg_hdr_lc'");
	_Static_assert(sizeof(s->rodata->cfg_no_arg_hash) == 1, "unexpected size of 'cfg_no_arg_hash'");
	_Static_assert(sizeof(s->rodata->cfg_no_sql) == 1, "unexpected size of 'cfg_no_sql'");
	_Static_assert(sizeof(s->rodata->cfg_file_sql_only) == 1, "unexpected size of 'cfg_file_sql_only'");
	_Static_assert(sizeof(s->rodata->cfg_file_sql_filtered) == 1, "unexpected size of 'cfg_file_sql_filtered'");
	_Static_assert(sizeof(s->rodata->cfg_bigram_separated) == 1, "unexpected size of 'cfg_bigram_separated'");
	_Static_assert(sizeof(s->rodata->cfg_end_on_status) == 1, "unexpected size of 'cfg_end_on_status'");
	_Static_assert(sizeof(s->rodata->cfg_monitored_len) == 4, "unexpected size of 'cfg_monitored_len'");
	_Static_assert(sizeof(s->rodata->cfg_monitored_path) == 128, "unexpected size of 'cfg_monitored_path'");
	_Static_assert(sizeof(s->rodata->cfg_file_sql_unfiltered) == 1, "unexpected size of 'cfg_file_sql_unfiltered'");
	_Static_assert(sizeof(s->rodata->cfg_file_sql_pred_args) == 1, "unexpected size of 'cfg_file_sql_pred_args'");
	_Static_assert(sizeof(s->rodata->cfg_sql_compact) == 1, "unexpected size of 'cfg_sql_compact'");
	_Static_assert(sizeof(s->rodata->cfg_syscall_filter) == 1, "unexpected size of 'cfg_syscall_filter'");
	_Static_assert(sizeof(s->rodata->cfg_syscall_filter_file) == 1, "unexpected size of 'cfg_syscall_filter_file'");
	_Static_assert(sizeof(s->rodata->cfg_mask_sql) == 1, "unexpected size of 'cfg_mask_sql'");
	_Static_assert(sizeof(s->rodata->cfg_mask_open) == 1, "unexpected size of 'cfg_mask_open'");
	_Static_assert(sizeof(s->rodata->cfg_mask_conn) == 1, "unexpected size of 'cfg_mask_conn'");
	_Static_assert(sizeof(s->rodata->cfg_raw_trace) == 1, "unexpected size of 'cfg_raw_trace'");
#ifdef __cplusplus
#undef _Static_assert
#endif
}

